(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.09, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*65, 0.11, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*100, 60+Math.cos(t*0.9+2)*75, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.08, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.13, 1.3, 0.85],
    [400+Math.cos(t*0.55+2)*80, 200+Math.sin(t*0.75+4)*60, 0.075, 2.1, 1.0]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5) * w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+0.7) * w * 0.5;
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, cou=cS/n;
  const s1=Math.sin(sx*0.035+sy*0.022+t*0.7), s2=Math.sin(sx*0.028-sy*0.038+t*1.0);
  const s3=Math.sin((sx+sy)*0.11+t*2.3)*0.25, s4=Math.sin((sx-sy)*0.095-t*1.8)*0.25;
  const s5=Math.sin(sx*0.06+sy*0.04-t*1.4)*0.15, s6=Math.sin(sx*0.02-sy*0.06+t*0.5)*0.15;
  const bg = (s1+s2)/2+s3+s4+s5+s6;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.4), sp2=Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3=Math.sin(dist*0.065-ang*2-t*2.0)*0.3;
  const spiral=(sp1+sp2)*0.35+sp3;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral)*2.0);
  const rd2 = Math.tanh((cou*0.8 - act*0.4 + inh*0.3 + spiral*0.5)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = rd1*0.55 + rd2*0.2 + cell*0.15 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,95],[18,95,120],[25,155,145],[140,190,130],
    [220,195,60],[215,130,65],[175,60,60],[120,30,55],[65,18,45],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const c0=pal[i], c1=pal[i+1];
  const edge=Math.abs(rd1)>0.65?1.2:Math.abs(rd2)>0.6?1.1:1.0;
  const glow=Math.max(0, (Math.abs(rd1)+Math.abs(rd2))*0.5-0.4)*0.6;
  const lum=0.85+Math.sin(rd1*Math.PI)*0.15+glow;
  const depth=0.92+Math.sin(dist*0.008-t*0.3)*0.08;
  return [
    Math.min(255, (c0[0]+(c1[0]-c0[0])*f)*lum*edge*depth)|0,
    Math.min(255, (c0[1]+(c1[1]-c0[1])*f)*lum*edge*depth)|0,
    Math.min(255, (c0[2]+(c1[2]-c0[2])*f)*lum*edge*depth)|0
  ];
}
